{"command": "cd /app && python3 - <<'EOF'
s = open('scan_persistence.sh').read()

# 1. Fix the broken cron timing-field regex (ERE bracket quirk with *)
old = '[[ ${toks[i]} =~ ^[0-9,/\\-A-Za-z*]+$ ]] || { ok=0; break; }'
new = '[[ ${toks[i]} =~ ^[*0-9,/-A-Za-z]+$ ]] || { ok=0; break; }'
assert old in s, "cron regex not found"
s = s.replace(old, new)

# 2. Allow bare command names (systemctl, journalctl, ...) in the
#    standard-path check so legitimate units are not flagged.
old = '''    # Any absolute path reference outside the standard system paths
    local tok
    for tok in $cmd; do
        case $tok in
            /*)
                case $tok in
                    /bin/*|/usr/bin/*|/sbin/*|/usr/sbin/*) ;;
                    /usr/lib/*|/lib/*) ;;
                    /etc/cron.hourly|/etc/cron.daily|/etc/cron.weekly|/etc/cron.monthly) ;;
                    /) ;;
                    *) return 0 ;;
                esac
                ;;
        esac
    done
    return 1'''
new = '''    # Any absolute path reference outside the standard system paths
    local tok
    for tok in $cmd; do
        case $tok in
            /*)
                case $tok in
                    /bin/*|/usr/bin/*|/sbin/*|/usr/sbin/*) ;;
                    /usr/lib/*|/usr/libexec/*|/lib/*) ;;
                    /etc/cron.hourly|/etc/cron.daily|/etc/cron.weekly|/etc/cron.monthly) ;;
                    /etc/fstab|/proc/self/mountinfo) ;;
                    /) ;;
                    *) return 0 ;;
                esac
                ;;
        esac
    done
    # bare command names (systemctl, journalctl, ...) are resolved via
    # PATH; only flag them if they are not standard system utilities
    local bare
    for bare in $cmd; do
        case $bare in
            -*) ;;
            *\"*|*\\$*|*\\'*|*@*|*=*) ;;
            systemctl|systemd-tmpfiles|systemd-sysusers|systemd-sysext \
            |systemd-machine-id-setup|systemd-tty-ask-password-agent \
            |journalctl|bootctl|udevadm|dbus-daemon|udevadm) ;;
            *)
                # unknown bare command: flag it
                return 0 ;;
        esac
    done
    return 1'''
assert old in s, "path block not found"
s = s.replace(old, new)

open('scan_persistence.sh','w').write(s)
print("patched")
EOF
bash -n /app/scan_persistence.sh && echo "syntax OK""}

